mapper.select:
SELECT id, title, detail, category, priority, due_date, budget_amount, actual_amount, completed, created_at, updated_at
FROM todos


        AND title LIKE CONCAT('%', #{keyword}, '%')


        AND category = #{category}


        AND due_date >= #{from}


        AND due_date <= #{to}


        AND priority = #{priority}


        AND budget_amount >= #{minAmount}


        AND actual_amount >= #{minAmount}


        AND budget_amount <= #{maxAmount}


        AND actual_amount <= #{maxAmount}


ORDER BY

    priority
    budget_amount
    actual_amount
    completed
    due_date


    DESC
    ASC

SELECT id, title, detail, category, priority, due_date, budget_amount, actual_amount, completed, created_at, updated_at
FROM todos
WHERE id = #{id}
